from flair.data import Sentence
tagger = get_plugin("tag")
__result__ = {}

raw_labels = state.get('labels', 'Chemical,Disease')
if isinstance(raw_labels, str):
    labels = [x.strip() for x in raw_labels.split(',') if x.strip()]
else:
    labels = [str(x).strip() for x in (raw_labels or []) if str(x).strip()]
if not labels:
    labels = ['Chemical', 'Disease']

for label in labels:
    __result__[label] = []

if tagger is None:
    # Sandbox/plugin unavailable: keep stable empty output shape.
    state['error'] = "Flair tagger unavailable"
else:
    sentence = Sentence(state.get('sentence', ''))
    try:
        tagger.predict(sentence)
        for entity in sentence.get_spans('ner'):
            if entity.tag in __result__:
                __result__[entity.tag].append(entity.text)
    except Exception as ex:
        state['error'] = f"Flair predict failed: {ex}"
